/**
 * Differential test: our GenBank reader against Biopython 1.88 (oracle JSON generated by
 * tools/oracle/genbank_oracle.py into test/oracle/genbank/biopython/).
 *
 * Every deliberate disagreement is listed in GENBANK_FEATURE_DEVIATIONS (see deviations.ts)
 * with its reason; everything else (names, descriptions, sequences, topology, molecule
 * types, header annotations, feature types, qualifiers and locations) must be identical.
 */
import { describe, expect, it } from 'vitest';
import { existsSync, readdirSync, readFileSync } from 'node:fs';
import { join } from 'node:path';
import { parseGenbank } from './genbank';
import { canonicalFromOracle, canonicalFromOurs, diffRecords, type OracleFile } from '../../test/oracle/genbank/compare';
import {
  GENBANK_FEATURE_DEVIATIONS,
  GENBANK_FILE_DEVIATIONS,
  GENBANK_RECORD_DEVIATIONS,
} from '../../test/oracle/genbank/deviations';

const FIXTURES = join(__dirname, '../../test/fixtures/genbank');
const ORACLE = join(__dirname, '../../test/oracle/genbank/biopython');

const files = readdirSync(FIXTURES).sort();

describe('GenBank reader agrees with Biopython 1.88', () => {
  it('has an oracle file for every fixture', () => {
    for (const f of files) expect(existsSync(join(ORACLE, `${f}.json`)), f).toBe(true);
  });

  for (const file of files) {
    it(file, () => {
      const oracle = JSON.parse(readFileSync(join(ORACLE, `${file}.json`), 'utf8')) as OracleFile;
      const ours = parseGenbank(readFileSync(join(FIXTURES, file), 'utf8'));
      const fileDeviation = GENBANK_FILE_DEVIATIONS.find((d) => d.file === file);
      if (oracle.error !== null) {
        // Biopython rejects the whole file; we must still read it (documented expectation).
        expect(fileDeviation, `Biopython failed (${oracle.error}); a file deviation must document it`).toBeDefined();
        expect(ours.records).toHaveLength(fileDeviation!.records);
        return;
      }
      expect(ours.records).toHaveLength(oracle.records.length);
      oracle.records.forEach((record, index) => {
        const deviations = GENBANK_FEATURE_DEVIATIONS.filter((d) => d.file === file && d.record === index);
        const tokenDeviation = GENBANK_RECORD_DEVIATIONS.some(
          (d) => d.file === file && d.record === index && d.field === 'moleculeType',
        );
        const diffs = diffRecords(canonicalFromOracle(record), canonicalFromOurs(ours.records[index]), deviations, {
          compareMoleculeToken: !tokenDeviation,
        });
        expect(diffs, `${file} record ${index}`).toEqual([]);
      });
    });
  }
});
